\begin{tikzpicture}[x=0.75mm,y=2.25mm,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{femaleBlue}{HTML}{268CFF}
\definecolor{maleRed}{HTML}{EF6068}
\definecolor{graphGrid}{HTML}{CCCCCC}
\path[use as bounding box] (-3,-4.7) rectangle (104,15.5);
\foreach \mass in {0,10,...,100} {
  \draw[graphGrid,line width=0.4pt,dash pattern=on 2mm off 1.5mm] (\mass,0) -- (\mass,15);
}
\draw[black,line width=0.5pt] (0,0) -- (100,0);
\foreach \mass in {0,10,...,100} {
  \draw[black,line width=0.4pt] (\mass,-0.16) -- (\mass,0.16);
  \node[anchor=north,inner sep=0pt,text=black,font=\fontsize{8.5}{10}\selectfont] at (\mass,-0.85) {\mass};
}
\foreach \mass/\count in {20/1,60/2,70/5,80/3,90/1} {
  \foreach \level in {1,...,\count} {
    \fill[maleRed] (\mass,{\level-0.4}) circle[radius=1.05mm];
  }
}
\foreach \mass/\count in {30/4,40/5,50/4} {
  \foreach \level in {1,...,\count} {
    \fill[femaleBlue] (\mass,{\level-0.4}) circle[radius=1.05mm];
  }
}
\fill[femaleBlue] (80,3.6) circle[radius=1.05mm];
\fill[femaleBlue] (1,-3.6) circle[radius=1.05mm];
\node[anchor=west,inner sep=0pt,text=black] at (4,-3.6) {Female};
\fill[maleRed] (28,-3.6) circle[radius=1.05mm];
\node[anchor=west,inner sep=0pt,text=black] at (31,-3.6) {Male};
\end{tikzpicture}
